.dialogue-speech-bubble {
  --dialogue-bubble-bg: rgba(255, 245, 211, 0.96);
  --dialogue-bubble-ink: #493523;
  --dialogue-bubble-accent: #b96d35;
  position: absolute;
  z-index: 4;
  width: max-content;
  min-width: 210px;
  max-width: 390px;
  padding: 18px 20px 15px;
  border: 3px solid var(--dialogue-bubble-accent);
  border-radius: 46% 38% 43% 35% / 24% 31% 26% 34%;
  background: var(--dialogue-bubble-bg);
  box-shadow: 0 13px 22px rgba(0, 0, 0, 0.3);
  color: var(--dialogue-bubble-ink);
  transform: translate(-50%, -100%) rotate(-0.4deg);
  pointer-events: none;
}

.dialogue-speech-bubble::before,
.dialogue-speech-bubble::after {
  position: absolute;
  left: calc(50% + var(--dialogue-tail-offset));
  content: "";
  transform: translateX(-50%);
}

.dialogue-speech-bubble::before {
  bottom: -25px;
  border: 13px solid transparent;
  border-top: 24px solid var(--dialogue-bubble-accent);
  border-bottom: 0;
}

.dialogue-speech-bubble::after {
  bottom: -18px;
  border: 10px solid transparent;
  border-top: 19px solid var(--dialogue-bubble-bg);
  border-bottom: 0;
}

