.npc-reaction-bubble.phase-in {
  animation: speech-fade-in 300ms ease-out both;
}

.npc-reaction-bubble.phase-out {
  animation: speech-fade-out 300ms ease-in both;
}

.speech-bubble {
  position: absolute;
  min-width: 200px;
  max-height: 190px;
  /*transform: translate(-50%, -100%);*/
  pointer-events: none;
  color: #4b3625;
  filter: drop-shadow(0 14px 22px rgba(0, 0, 0, 0.34));
  opacity: 1;
  box-sizing: border-box;
}

.speech-bubble.beat-resizing {
  transition: width 400ms ease-in-out, height 400ms ease-in-out, left 400ms ease-in-out,
    right 400ms ease-in-out, bottom 400ms ease-in-out;
}

.speech-bubble.phase-beat-out .speech-text {
  animation: speech-text-out 200ms ease-in both;
}

.speech-bubble.phase-beat-in .speech-text {
  animation: speech-text-in 200ms ease-out both;
}

.speech-bubble.phase-in {
  animation: speech-fade-in 300ms ease-out both;
}

.speech-bubble.phase-out {
  animation: speech-fade-out 300ms ease-in both;
}

.speech-blobs {
  position: relative;
  z-index: 1;
  max-height: inherit;
  padding: 12px 16px;
  overflow: visible;
  filter: url("#speech-goo");
  box-sizing: border-box;
  height: 100%;
}

.speech-blob-top,
.speech-blob-bottom {
  position: absolute;
  left: 0;
  right: 0;
  z-index: 0;
  background: #fff4cf;
}

.speech-blob-top {
  top: 0;
  height: 78%;
  border-radius: 42% 44% 32% 36% / 130% 125% 95% 110%;
  animation: speech-blob 1.7s cubic-bezier(0.37, 0, 0.63, 1) infinite alternate;
}

.speech-blob-bottom {
  left: 4%;
  right: 4%;
  bottom: 0;
  height: 45%;
  border-radius: 16% 12% 28% 24% / 80% 90% 130% 120%;
  animation: speech-blob 1.25s cubic-bezier(0.37, 0, 0.63, 1) 120ms infinite alternate-reverse;
}

.speech-text {
  position: relative;
  z-index: 2;
  max-height: 150px;
  overflow: visible;
  padding: 0 12px;
  color: #5e513e;
  font-size: 20px;
  line-height: 1.32;
  font-weight: 400;
  overflow-wrap: anywhere;
  text-align: center;
}

.speech-text-measure {
  position: absolute;
  left: -10000px;
  top: -10000px;
  visibility: hidden;
  box-sizing: border-box;
  max-height: none;
  pointer-events: none;
}

.speech-measure {
  position: absolute;
  left: -10000px;
  top: -10000px;
  visibility: hidden;
  filter: none;
}

.speech-measure .speech-tail {
  display: none;
}

.speech-speaker {
  position: absolute;
  left: 22px;
  top: -19px;
  z-index: 2;
  padding: 5px 16px 6px;
  border-radius: 45% 36% 42% 34% / 100% 80% 100% 90%;
  background: #d48638;
  color: #2c1711;
  font-weight: 400;
  font-size: 15px;
  letter-spacing: 1px;
  transform: rotate(-4deg);
  box-shadow: 0 3px 0 rgba(96, 45, 22, 0.22);
  animation: speech-speaker-float 1.45s cubic-bezier(0.37, 0, 0.63, 1) 80ms infinite alternate;
}

.speech-tail {
  position: absolute;
  z-index: 0;
  bottom: -56px;
  width: 132px;
  height: 82px;
  overflow: visible;
  animation: speech-tail 1.35s cubic-bezier(0.37, 0, 0.63, 1) 0.2s infinite alternate;
}

.speech-tail path {
  fill: #fff4cf;
}

.speech-bubble.tail-left .speech-tail {
  left: 56px;
  bottom: -32px;
  transform-origin: 100% 0;
  transform: rotate(-10deg);
}

.speech-bubble.tail-right .speech-tail {
  right: -76px;
  transform-origin: 0 0;
  transform: scaleX(-1) rotate(-10deg);
}

.speech-bubble.reject .speech-blob-top,
.speech-bubble.reject .speech-blob-bottom,
.speech-bubble.reject .speech-tail path {
  background: #ffe1c8;
  fill: #ffe1c8;
}

.speech-bubble.reject .speech-speaker {
  background: #c65f3f;
  color: #fbe8cf;
}

@keyframes speech-blob {
  from {
    transform: rotate(0.45deg) scale(1.006);
  }
  to {
    transform: rotate(-0.45deg) scale(0.985);
  }
}

@keyframes speech-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes speech-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes speech-text-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes speech-text-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes speech-tail {
  from {
    margin-bottom: 0;
  }
  to {
    margin-bottom: 5.5px;
  }
}

@keyframes speech-speaker-float {
  from {
    margin-top: 0;
  }
  to {
    margin-top: 4px;
  }
}

